import 'package:flutter/widgets.dart';

/// Self-contained string table for the NekoSim layer.
///
/// The host app's l10n is generated from .arb via flutter gen-l10n; editing
/// those generated files by hand is fragile. NekoSim keeps its own table
/// (same 9 locales) until the strings are upstreamed into the arb workflow.
class NekoSimStrings {
  final Map<String, String> _m;
  const NekoSimStrings._(this._m);

  static NekoSimStrings of(BuildContext context) {
    final locale = Localizations.localeOf(context);
    return forLocale(
      locale.languageCode,
      countryCode: locale.countryCode,
      scriptCode: locale.scriptCode,
    );
  }

  static NekoSimStrings forLocale(
    String languageCode, {
    String? countryCode,
    String? scriptCode,
  }) {
    switch (languageCode) {
      case 'zh':
        final traditional = scriptCode == 'Hant' ||
            countryCode == 'TW' ||
            countryCode == 'HK' ||
            countryCode == 'MO';
        return NekoSimStrings._(traditional ? _zhTw : _zh);
      case 'ja':
        return const NekoSimStrings._(_ja);
      case 'ko':
        return const NekoSimStrings._(_ko);
      case 'de':
        return const NekoSimStrings._(_de);
      case 'es':
        return const NekoSimStrings._(_es);
      case 'fr':
        return const NekoSimStrings._(_fr);
      case 'it':
        return const NekoSimStrings._(_it);
      default:
        return const NekoSimStrings._(_en);
    }
  }

  String _t(String k) => _m[k] ?? _en[k] ?? k;

  String get assetsTitle => _t('assetsTitle');
  String get tabAssets => _t('tabAssets');
  String get addToAssets => _t('addToAssets');
  String get importLpa => _t('importLpa');
  String get addAsset => _t('addAsset');
  String get cloudReminders => _t('cloudReminders');
  String get exportJson => _t('exportJson');
  String get exportCsv => _t('exportCsv');
  String get importData => _t('importData');
  String get noAssets => _t('noAssets');
  String get noAssetsHint => _t('noAssetsHint');
  String get deleteAssetQ => _t('deleteAssetQ');
  String get cancel => _t('cancel');
  String get delete => _t('delete');
